#include <QApplication>
#include <QPushButton>
#include <QFileDialog>
#include <QDir>
#include <QMessageBox>
#include <QDebug>
#include <QFileInfo>

#include <xlsxio.h> // For reading Excel files

// Function to convert an Excel file to CSV
bool convertExcelToCsv(const QString& excelFilePath, const QString& csvFilePath) {
    xlsxio_t xlsx = xlsx_open_ liye(excelFilePath.toLocal8Bit().constData(), 0);
    if (!xlsx) {
        qWarning() << "Failed to open Excel file:" << excelFilePath;
        return false;
    }

    FILE* csv_file = fopen(csvFilePath.toLocal8Bit().constData(), "w");
    if (!csv_file) {
        qWarning() << "Failed to create CSV file:" << csvFilePath;
        xlsx_close(xlsx);
        return false;
    }

    int num_sheets = xlsx_get_sheet_count(xlsx);
    for (int i = 0; i < num_sheets; ++i) {
        xlsx_set_sheet(xlsx, i);
        int num_rows = xlsx_get_rows(xlsx);
        for (int row = 0; row < num_rows; ++row) {
            int num_cols = xlsx_get_cols(xlsx, row);
            for (int col = 0; col < num_cols; ++col) {
                const char* value = xlsx_cell_get(xlsx, row, col);
                if (value) {
                    // Basic CSV escaping: if value contains comma or quote, enclose in quotes and double up quotes
                    QString cellValue = QString::fromUtf8(value);
                    if (cellValue.contains(',') || cellValue.contains('"')) {
                        cellValue.replace('"', "\"\""); // Double up existing quotes
                        cellValue.prepend('"');
                        cellValue.append('"');
                    }
                    fprintf(csv_file, "%s", cellValue.toLocal8Bit().constData());
                }
                if (col < num_cols - 1) {
                    fprintf(csv_file, ",");
                }
            }
            fprintf(csv_file, "\n");
        }
        if (i < num_sheets - 1) {
            fprintf(csv_file, "\n---\n\n"); // Separator for different sheets
        }
    }

    fclose(csv_file);
    xlsx_close(xlsx);
    return true;
}

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    QWidget window;
    QVBoxLayout *layout = new QVBoxLayout(&window);

    QPushButton *selectDirButton = new QPushButton("Select Directory and Convert Excel to CSV");
    layout->addWidget(selectDirButton);

    QObject::connect(selectDirButton, &QPushButton::clicked, [&]() {
        QString directory = QFileDialog::getExistingDirectory(&window, "Select Directory", QDir::homePath());

        if (directory.isEmpty()) {
            QMessageBox::warning(&window, "No Directory Selected", "You did not select a directory.");
            return;
        }

        QDir dir(directory);
        QString csvOutputDirName = "Converted_CSVs";
        QString csvOutputDirPath = dir.filePath(csvOutputDirName);

        // Create the output directory if it doesn't exist
        if (!dir.exists(csvOutputDirName)) {
            if (!dir.mkdir(csvOutputDirName)) {
                QMessageBox::critical(&window, "Error", "Could not create output directory: " + csvOutputDirPath);
                return;
            }
        }

        qDebug() << "Processing directory:" << directory;

        QStringList filters;
        filters << "*.xlsx" << "*.xls"; // Add more formats if needed

        QFileInfoList files = dir.entryInfoList(filters, QDir::Files);

        int convertedCount = 0;
        for (const QFileInfo &fileInfo : files) {
            QString excelFilePath = fileInfo.absoluteFilePath();
            QString baseName = fileInfo.baseName();
            QString csvFileName = baseName + ".csv";
            QString csvFilePath = csvOutputDirPath + "/" + csvFileName;

            qDebug() << "Converting:" << excelFilePath << "to" << csvFilePath;

            if (convertExcelToCsv(excelFilePath, csvFilePath)) {
                convertedCount++;
            } else {
                QMessageBox::warning(&window, "Conversion Error", "Failed to convert file: " + fileInfo.fileName());
            }
        }

        if (convertedCount > 0) {
            QMessageBox::information(&window, "Conversion Complete",
                                     QString("%1 Excel files converted to CSVs in:\n%2")
                                     .arg(convertedCount)
                                     .arg(csvOutputDirPath));
        } else {
            QMessageBox::information(&window, "No Excel Files Found",
                                     "No Excel files (.xlsx, .xls) were found in the selected directory to convert.");
        }
    });

    window.setWindowTitle("Excel to CSV Converter");
    window.show();

    return app.exec();
}
```

**Explanation and Setup:**

1.  **Qt5 Installation:**
    *   Make sure you have Qt5 installed on your system. You can download it from the [official Qt website](https://www.qt.io/download-qt-installer/).
    *   When installing, ensure you select the components for your desired compiler (e.g., MinGW for Windows, Clang for macOS/Linux).

2.  **`xlsxio` Library:**
    *   This code relies on the `xlsxio` library for reading `.xlsx` files. `xlsxio` is a C library.
    *   **How to get `xlsxio`:**
        *   **Download:** You can download the source code from its [GitHub repository](https://github.com/darkf/xlsxio).
        *   **Build:** Compile `xlsxio` on your system. This usually involves running `make` or a similar build command in the extracted `xlsxio` directory. You'll typically get a `libxlsxio_*.a` or `libxlsxio_*.so`/`.dylib` file.
        *   **Include Path:** During compilation with Qt Creator or qmake, you'll need to tell the compiler where to find the `xlsxio` header files (usually in an `include` directory within the `xlsxio` source).
        *   **Linker Path:** You'll also need to tell the linker where to find the compiled `xlsxio` library file.

3.  **Qt Project File (`.pro`):**
    *   You'll need a `.pro` file to configure your Qt project. This tells Qt how to build your application, which modules to use, and how to link external libraries.

    ```pro
    QT += widgets # For GUI elements like QPushButton, QMessageBox, etc.

    SOURCES += main.cpp # Your main C++ source file

    # -- xlsxio Configuration --
    # Adjust these paths to where you have the xlsxio library and headers
    INCLUDEPATH += /path/to/xlsxio/include # e.g., C:/libs/xlsxio/include
    LIBS += -L/path/to/xlsxio/lib -lxlsxio # e.g., -LC:/libs/xlsxio/lib -lxlsxio

    # For Windows, you might need to specify the full path to the .lib file if it's not in a standard lib directory
    # LIBS += C:/path/to/xlsxio/lib/xlsxio.lib
    ```
    **Important:** Replace `/path/to/xlsxio/include` and `/path/to/xlsxio/lib` with the actual paths on your system.

4.  **How to Compile and Run:**
    *   **Using Qt Creator:**
        1.  Create a new "Qt Widgets Application" project.
        2.  Replace the default `main.cpp` content with the code above.
        3.  Edit the `.pro` file as described above, making sure the `INCLUDEPATH` and `LIBS` are correct for `xlsxio`.
        4.  Build and run your project.
    *   **Using `qmake` and `make` from the command line:**
        1.  Save the C++ code as `main.cpp`.
        2.  Create a `.pro` file (e.g., `excelconverter.pro`) with the contents mentioned above.
        3.  Open a terminal or command prompt and navigate to the directory where you saved these files.
        4.  Run `qmake excelconverter.pro` (or your `.pro` file name). This will generate a `Makefile`.
        5.  Run `make` (or `mingw32-make` on Windows with MinGW).
        6.  Execute the generated application (e.g., `./excelconverter` on Linux/macOS, `excelconverter.exe` on Windows).

